both.content:
otelcol.receiver.otlp "default" {
  http {}
  grpc {}

  output {
    metrics = [otelcol.exporter.otlphttp.prod.input]
    logs    = [otelcol.exporter.otlphttp.prod.input]
    traces  = [otelcol.exporter.otlphttp.prod.input]
  }
}

otelcol.exporter.otlphttp "prod" {
  client {
    endpoint = sys.env("OTLP_ENDPOINT_PROD")
  }
}

